    class Engine,

    std::size_t W,

    class UIntType

    >
class independent_bits_engine;

examples.code:
#include <random>
#include <sstream>
#include <cassert>
#include <iostream>

int main() {
    using Engine = std::independent_bits_engine<std::minstd_rand, 16, unsigned>;
    Engine engine{42};
    Engine copy{42};
    assert(engine == copy);
    auto value = engine();
    assert(value >= Engine::min() && value <= Engine::max());
    engine.seed(42);
    engine.discard(3);
    for (int i = 0; i < 3; ++i) {
        (void)copy();
    }
    assert(engine == copy);
    (void)engine.base(); // Inspect the underlying engine without advancing it.
    std::stringstream saved;
    saved << engine;
    saved >> copy;
    assert(copy == engine);
    std::cout << "Checks passed\n";
}
